// GridView — Gtk.GridView
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles gridview with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { ListTabBehavior, Orientation } from "@/lib/enums"

export interface GridViewProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.GridView */
  enableRubberband?: boolean

  /** ListItemFactory, from Gtk.GridView */
  factory?: ReactNode

  /** guint, from Gtk.GridView */
  maxColumns?: number

  /** guint, from Gtk.GridView */
  minColumns?: number

  /** SelectionModel, from Gtk.GridView */
  model?: ReactNode

  /** Orientation, from Gtk.ListBase */
  orientation?: Orientation

  /** gboolean, from Gtk.GridView */
  singleClickActivate?: boolean

  /** ListTabBehavior, from Gtk.GridView */
  tabBehavior?: ListTabBehavior
}

export function GridView({ className, children }: GridViewProps) {
  return (
    <div className={cn("p-[15px]", className)}>
      {children}
    </div>
  )
}
